"let activeServer = null;
let activePort = DEFAULT_PORT;

// ---------------------------------------------------------------------------
// webOS Luna Service Integration
// ---------------------------------------------------------------------------
let lunaService = null;
try {
  const Service = require('webos-service');
  lunaService = new Service('com.cinejoy.tv.service');

  lunaService.register('ping', function (message) {
    message.respond({ returnValue: true, status: 'ok', port: activePort });
  });

  lunaService.register('health', function (message) {
    message.respond({ returnValue: true, status: 'ok', uptime: process.uptime(), port: activePort });
  });
  console.log('[com.cinejoy.tv.service] Registered with webOS Luna Service bus');
} catch (err) {
  // Gracefully continue when running in standard Node.js (outside webOS)
}"

